css:
.fx-hmega .pg{width:min(980px,100%);margin:0 auto;padding:3em 1.25em 6em;display:grid;gap:3.5em}
.fx-hmega .pg section{display:grid;gap:.9em}
.fx-hmega .pg .k{font-size:.75em;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--accent)}
.fx-hmega .pg h2{font-size:clamp(1.6em,3.4vw,2.2em)}
.fx-hmega .pg p{opacity:.7;max-width:60ch}
.fx-hmega .pg .fx-art{aspect-ratio:21/9;border-radius:var(--radius);margin-top:.4em}
.fx-art{position:relative;overflow:hidden;background:linear-gradient(135deg,var(--primary),color-mix(in srgb,var(--primary) 45%,var(--accent)))}
.fx-art::before,.fx-art::after{content:"";position:absolute;border-radius:50%;background:color-mix(in srgb,var(--accent) 60%,#fff);opacity:.35}
.fx-art::before{width:60%;aspect-ratio:1;right:-12%;top:-20%}.fx-art::after{width:38%;aspect-ratio:1;left:8%;bottom:-18%;opacity:.25;background:#fff}
.fx-art.a2{background:linear-gradient(160deg,var(--accent),color-mix(in srgb,var(--accent) 40%,var(--primary)))}
.fx-art.a3{background:linear-gradient(200deg,color-mix(in srgb,var(--primary) 70%,#000),var(--accent))}
.fx-hmega{background:var(--surface)}
.fx-hmega .hd{position:relative;z-index:30;display:flex;align-items:center;gap:2em;padding:1.1em max(5vw,1.25em);background:var(--surface);border-bottom:1px solid var(--border)}
.fx-hmega .logo{display:inline-flex;align-items:center;gap:.55em;font:600 1.35em var(--font-heading);color:var(--text);text-decoration:none}
.fx-hmega .logo i{width:.8em;height:.8em;border-radius:30%;background:linear-gradient(135deg,var(--primary),var(--accent))}
.fx-hmega nav>ul{display:flex;gap:.3em;list-style:none;margin:0;padding:0}
.fx-hmega nav a.top,.fx-hmega nav button{all:unset;box-sizing:border-box;display:inline-flex;align-items:center;gap:.4em;padding:.6em .9em;border-radius:calc(var(--radius)*.7);font:600 .95em var(--font-body);color:var(--text);cursor:pointer;transition:background .2s}
.fx-hmega nav button::after{content:"";width:.45em;height:.45em;border:solid currentColor;border-width:0 1.6px 1.6px 0;transform:rotate(45deg) translateY(-2px);transition:transform calc(.25s/var(--speed))}
.fx-hmega li.open>button,.fx-hmega nav button:hover,.fx-hmega nav a.top:hover{background:color-mix(in srgb,var(--text) 7%,transparent)}
.fx-hmega li.open>button::after{transform:rotate(225deg) translate(-2px,-1px)}
.fx-hmega nav a.top:focus-visible,.fx-hmega nav button:focus-visible,.fx-hmega .logo:focus-visible,.fx-hmega .mp a:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.fx-hmega .sp{flex:1}.fx-hmega .login{font-weight:600;font-size:.95em;color:var(--text);text-decoration:none}
.fx-hmega .mp{position:absolute;left:0;right:0;top:100%;background:var(--surface);border-bottom:1px solid var(--border);box-shadow:0 40px 60px -40px rgba(0,0,0,.45);opacity:0;visibility:hidden;transform:translateY(-8px);transition:opacity calc(.25s/var(--speed)),transform calc(.25s/var(--speed)),visibility 0s calc(.25s/var(--speed))}
.fx-hmega li.open>.mp{opacity:1;visibility:visible;transform:none;transition-delay:0s}
.fx-hmega .mi{width:min(1080px,100%);margin:0 auto;padding:2em 1.25em 2.2em;display:grid;grid-template-columns:1fr 1fr 1.05fr;gap:2.4em}
.fx-hmega .col h3{font:700 .72em var(--font-body);letter-spacing:.14em;text-transform:uppercase;opacity:.55;margin-bottom:.9em}
.fx-hmega .col a{display:grid;grid-template-columns:2.4em 1fr;gap:.2em .8em;padding:.6em .5em;margin:0 -.5em;border-radius:calc(var(--radius)*.7);text-decoration:none;color:var(--text);transition:background .2s}
.fx-hmega .col a:hover{background:color-mix(in srgb,var(--primary) 8%,transparent)}
.fx-hmega .col a i{grid-row:span 2;width:2.4em;height:2.4em;border-radius:30%;background:color-mix(in srgb,var(--primary) 14%,var(--surface));display:grid;place-items:center;font-style:normal;color:var(--primary);font-weight:700}
.fx-hmega .col a:nth-child(even) i{background:color-mix(in srgb,var(--accent) 16%,var(--surface));color:var(--accent)}
.fx-hmega .col b{font-size:.95em}.fx-hmega .col span{font-size:.82em;opacity:.62;line-height:1.4}
.fx-hmega .feat{border-radius:var(--radius);border:1px solid var(--border);overflow:hidden;display:grid;text-decoration:none;color:var(--text);align-self:start}
.fx-hmega .feat .fx-art{aspect-ratio:16/9}.fx-hmega .feat div{padding:1em 1.1em 1.2em;display:grid;gap:.3em}.fx-hmega .feat b{font:600 1.1em var(--font-heading)}.fx-hmega .feat span{font-size:.85em;opacity:.65}
.fx-hmega .feat em{font-style:normal;font-weight:700;font-size:.85em;color:var(--primary)}
@media(max-width:860px){.fx-hmega .mi{grid-template-columns:1fr;gap:1.2em;padding:1.2em 1.25em}.fx-hmega .feat{display:none}.fx-hmega .login{display:none}.fx-hmega .hd{gap:.6em}.fx-hmega .logo{font-size:1.1em}.fx-hmega nav a.top,.fx-hmega nav button{padding:.55em .5em;font-size:.85em}.fx-hmega .col+.col{display:none}.fx-hmega .sp{display:none}.fx-hmega .hd{flex-wrap:wrap}.fx-hmega nav{order:3;width:100%;margin:0 -.5em}.fx-hmega nav>ul{flex-wrap:wrap}}
@media(prefers-reduced-motion:reduce){.fx-hmega .mp,.fx-hmega nav button::after{transition:none}}
/* touch: :hover mirrored as .is-tap */
.fx-hmega nav button.is-tap{background:color-mix(in srgb,var(--text) 7%,transparent)}
.fx-hmega nav a.top.is-tap{background:color-mix(in srgb,var(--text) 7%,transparent)}
.fx-hmega .col a.is-tap{background:color-mix(in srgb,var(--primary) 8%,transparent)}
